from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts import time_to_seconds
from .connector import connect
from .hardware import Quanta, Dell, Switch
from .nokia import Nokia1830Tps
from .autodiscovery import find_switch_type


class switch(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    alias_handler, store = aliasing_scope(name=__name__, lookup_arg='connection',
                                          lookup_type=Switch)

    models = {'dell': Dell, 'quanta': Quanta, 'auto': find_switch_type, "nokia1830tps": Nokia1830Tps}

    def connect_to(self, hostname, username, password, type='auto',
                   port=None, alias=None, timeout=30.0):
        """ Connect to a switch.

        Connects to a switch using the given credentials and address.
        The type argument is either:
         - 'auto': let the library deduce the correct setting
         - 'dell': for Dell S4048-ON
         - 'quanta': for Quanta T3048-LY8, with Runtime Code 2.4.11.00.

        The library has been tested with the specified switch models. Others
        might work too, but aren't actively supported.

        :param hostname: Hostname of the switch to connect to.
        :param username: Username for the switch CLI.
        :param password: Password for the switch CLI.
        :param type: Type of the switch - see description above.
        :param port: (Optional) port on which the CLI is listening for
            incomming connections. By default, 22 (SSH) is used.
        :param alias: (Optional) alias which the connection will be identified
            by, when using keywords that utilize it. If none given, the
            connection will be used whenever other keywords also receive no
            alias.
        :param timeout: (Optional) timeout used when connecting to the CLI,
            specified in robot framework time format. Defaults to 30 seconds.
        """
        if port is None:
            port = 22
        port = int(port)
        timeout = time_to_seconds(timeout)

        switch_cls = self.models[type]
        switch = connect(switch_cls, hostname, username, password,
                         port=port, timeout=timeout)
        self.store.add(switch, alias)
        return switch

    @alias_handler.implicit_lookup
    def enable_interface(self, interface_id, connection=None):
        """ Enable the port with the given id.

        Runs appropriate commands via switch CLI to automatically enable the
        interface designated by the given interface_id.

        :param interface_id: ID of the interface that should be enabled.
        :param connection: alias of the connection to use or an instance of
            Switch.
        """
        connection.enable_interface(interface_id)

    @alias_handler.implicit_lookup
    def disable_interface(self, interface_id, connection=None):
        """ Disable the port with the given id.

        Runs appropriate commands via switch CLI to automatically disable the
        interface designated by the given interface_id.

        :param interface_id: ID of the interface that should be disabled.
        :param connection: alias of the connection to use or an instance of
            Switch.
        """
        connection.disable_interface(interface_id)

    @alias_handler.implicit_lookup
    def interface_active(self, interface_id, connection=None):
        """ Check whether an interface with the given id is enabled.


        :param interface_id: ID of the interface that should be checked.
        :param connection: alias of the connection to use or an instance of
            Switch.
        :returns bool: True if the interface with the given ID is enabled,
            False otherwise.
        """
        return connection.interface_active(interface_id)
